CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, nom TEXT NOT NULL, telephone TEXT, email TEXT, solde_ar INTEGER NOT NULL DEFAULT 0, tarif_sms_ar INTEGER NOT NULL DEFAULT 20, minimum_mensuel_ar INTEGER NOT NULL DEFAULT 0, statut TEXT NOT NULL DEFAULT 'actif' CHECK (statut IN ('actif','suspendu')), cree_le INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS utilisateurs (id TEXT PRIMARY KEY, client_id TEXT REFERENCES clients(id), email TEXT NOT NULL UNIQUE, mot_de_passe_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('super_admin','client_admin','client_staff')), actif INTEGER NOT NULL DEFAULT 1, cree_le INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS appareils (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), nom TEXT NOT NULL, operateur TEXT NOT NULL CHECK (operateur IN ('mvola','orange','airtel')), numero TEXT, jeton_hash TEXT, dernier_contact INTEGER, statut TEXT NOT NULL DEFAULT 'en_attente' CHECK (statut IN ('en_attente','actif','desactive')), cree_le INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sms (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), appareil_id TEXT NOT NULL REFERENCES appareils(id), operateur TEXT NOT NULL, expediteur TEXT NOT NULL, texte TEXT NOT NULL, empreinte TEXT NOT NULL, montant_ar INTEGER, reference TEXT, numero_payeur TEXT, statut TEXT NOT NULL CHECK (statut IN ('reconnu','ignore')), facture INTEGER NOT NULL DEFAULT 0, recu_le INTEGER NOT NULL, cree_le INTEGER NOT NULL, UNIQUE (appareil_id, empreinte));
CREATE TABLE IF NOT EXISTS mouvements_credit (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), type TEXT NOT NULL CHECK (type IN ('recharge','sms','ajustement')), montant_ar INTEGER NOT NULL, sms_id TEXT REFERENCES sms(id), note TEXT, cree_le INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_utilisateurs_client ON utilisateurs(client_id);
CREATE INDEX IF NOT EXISTS idx_appareils_client ON appareils(client_id);
CREATE INDEX IF NOT EXISTS idx_sms_client_date ON sms(client_id, recu_le);
CREATE INDEX IF NOT EXISTS idx_sms_client_ref ON sms(client_id, reference);
CREATE INDEX IF NOT EXISTS idx_mouv_client_date ON mouvements_credit(client_id, cree_le);
